import type { PreviewName } from "@registry/pdf/previews";
import Image from "next/image";
import manifest from "../../../public/previews/pdf/manifest.json";

// Static renders of the registry previews, generated by
// `pnpm --filter @repo/registries pdf:previews` (PDF + one PNG per page).
const PREVIEW_BASE = "/previews/pdf";

interface PdfPreviewProps {
  /** Max height of the scrollable frame, in px. */
  height?: number;
  name: PreviewName;
}

export function PdfPreview({ name, height = 420 }: PdfPreviewProps) {
  const entry = (manifest as Record<string, PreviewManifestEntry>)[name];
  if (!entry) {
    throw new Error(
      `PdfPreview: no rendered preview for "${name}". Run \`pnpm --filter @repo/registries pdf:previews\`.`
    );
  }
  const pages = Array.from({ length: entry.pages }, (_, i) => i + 1);

  return (
    <figure className="not-prose flex flex-col gap-2">
      <div
        className="flex flex-col items-center gap-4 overflow-y-auto rounded-lg border bg-muted p-4 sm:p-6"
        style={{ maxHeight: height }}
      >
        {pages.map((page) => (
          <Image
            alt={`${name} preview, page ${page} of ${entry.pages}`}
            className="h-auto w-full max-w-xl bg-white shadow-md ring-1 ring-black/5"
            height={entry.height}
            key={page}
            priority={page === 1}
            sizes="(min-width: 768px) 576px, 100vw"
            src={`${PREVIEW_BASE}/${name}-${page}.png`}
            width={entry.width}
          />
        ))}
      </div>
      <figcaption className="flex items-center justify-between text-muted-foreground text-xs">
        <span>
          {entry.pages} page{entry.pages > 1 ? "s" : ""}
          {entry.pages > 1 ? " — scroll to see them all" : ""}
        </span>
        <a
          className="font-medium text-foreground underline-offset-4 hover:underline"
          href={`${PREVIEW_BASE}/${name}.pdf`}
          rel="noopener"
          target="_blank"
        >
          Open PDF ↗
        </a>
      </figcaption>
    </figure>
  );
}

interface PreviewManifestEntry {
  height: number;
  pages: number;
  width: number;
}
